parameters.jsCode:
const item = $input.first().json;
const raw = item.output || item.text || item;
let out = (typeof raw === "object") ? raw : {};

if (typeof raw === "string") {
  let cleaned = raw.trim().replace(/^\`\`\`(?:json)?\s*/i, "").replace(/\s*\`\`\`$/i, "").trim();
  try {
    out = JSON.parse(cleaned);
  } catch (e) {
    const match = cleaned.match(/\{[\s\S]*\}/);
    if (match) { try { out = JSON.parse(match[0]); } catch (e2) {} }
  }
}
if (out && out.output) { out = out.output; }

const currency = out.currency || "INR";
let estimates = Array.isArray(out.estimates) ? out.estimates : [];

// Resilient fallback if LLM omitted estimates
if (estimates.length === 0) {
  const opps = $("When Called by Commander").first().json.opportunities || [];
  estimates = opps.map(o => ({
    company: o.company,
    partnership_type: o.partnership_type || o.type || "Sponsorship",
    deal_value_low: 100000,
    deal_value_high: 250000,
    probability: 0.7,
    estimated_cost: 30000,
    basis: "ESTIMATE",
    assumptions: ["Standard tier sponsorship package"],
    notes: o.pitch_angle || "Strategic partnership"
  }));
}

const round = (n) => Math.round((Number(n) || 0));

const financial_analysis = estimates.map((e) => {
  const low = Number(e.deal_value_low) || 0;
  const high = Number(e.deal_value_high) || 0;
  const mid = (low + high) / 2;
  const prob = Math.max(0, Math.min(1, Number(e.probability) || 0));
  const cost = Number(e.estimated_cost) || 0;

  const expected_value = round(mid * prob);
  const estimated_profit = round(mid - cost);
  const expected_profit = round((mid - cost) * prob);
  const roi = cost > 0 ? Number((((mid - cost) / cost)).toFixed(2)) : null;
  const spread = mid > 0 ? (high - low) / mid : 1;
  const financial_confidence = Number((prob * (1 - Math.min(spread, 1) * 0.3)).toFixed(2));

  return {
    company: e.company,
    partnership_type: e.partnership_type || "",
    currency,
    deal_value_range: { low: round(low), high: round(high), mid: round(mid) },
    probability: prob,
    expected_value,
    estimated_cost: round(cost),
    estimated_profit,
    expected_profit,
    roi,
    financial_confidence,
    basis: e.basis || "ASSUMPTION",
    assumptions: Array.isArray(e.assumptions) ? e.assumptions : [],
    notes: e.notes || "",
  };
});

financial_analysis.sort((a, b) => b.expected_profit - a.expected_profit);
const totals = financial_analysis.reduce((acc, f) => {
  acc.total_expected_value += f.expected_value;
  acc.total_expected_profit += f.expected_profit;
  return acc;
}, { total_expected_value: 0, total_expected_profit: 0 });

return [{
  json: {
    event: $("When Called by Commander").first().json.event || {},
    currency,
    financial_analysis,
    portfolio: {
      opportunities_analyzed: financial_analysis.length,
      total_expected_value: round(totals.total_expected_value),
      total_expected_profit: round(totals.total_expected_profit),
    },
  },
}];
